def apply_fixes(spec, result, only=None):
    """Return a copy of the spec with every inflating step fixed (or just step `only`), plus what changed."""
    new = clone(spec)
    changes = []
    inserts = []
    for r in result.steps:
        if not r.inflated or (only is not None and r.index != only):
            continue
        step = new["steps"][r.index]
        fixed, why = suggest_fix(step)
        if fixed is not None:
            new["steps"][r.index] = fixed
        else:
            inserts.append(r.index + 1)
        changes.append(f"Step {r.index + 1}: {why}")
        new.setdefault("fix_log", []).append({
            "step": r.index + 1, "was": r.label, "rows": r.rows_out, "samples": r.samples_out,
            "patients": r.patients_out, "examples": r.duplicate_examples[:5], "fix": why,
            "inserted_step": fixed is None, "rows_per_sample": r.duplicate_counts})

def _run(spec, store, fix):
    first = engine.run(spec, store)
    if fix and any(s.inflated for s in first.steps):
        spec, changes = engine.apply_fixes(spec, first)
        return spec, engine.run(spec, store), first, changes
    return spec, first, first, []


def build_cohort(query, out_dir="output", store=None, data_dir=None, ai="auto", fix=True, accept_unparsed=False,
                 team="Cohort Studio team", write=True, log=None, drafter=None, **ai_options):
    """Draft (if needed), run, fix inflation, evaluate and export one cohort. ai: "auto", "own" or "off" (see
    llm.draft_spec); ai_options: provider, api_key, model, base_url or client for your own model. drafter: a
    function request -> (spec, route) used instead of llm.draft_spec (the hosted MCP server drafts on the server)."""
    store = store or DataStore(data_dir)
    kind, q = as_query(query)
    if kind == "spec":
        spec, route = q, {"used": "definition", "label": "cohort definition, run as written", "tried": []}
    elif drafter is not None:
        spec, route = drafter(q)
    else:
        spec, route = draft_spec(q, store, ai=ai, log=log, **ai_options)
    if accept_unparsed:
        spec["unparsed_confirmed"] = True
    spec, result, first, fixes = _run(spec, store, fix)

v = verdict.evaluate(result, store)
out = exports.write_all(result, v, store, out_dir, team=team) if write else None
return CohortRun(spec.get("request", q if kind == "text" else ""), spec, result, first, fixes, v, route, out)

def _check_files(self):
    expected = {}
    sources = self.data_dir / "sources.csv"
    if sources.exists():
        with open(sources) as f:
            expected = {row["file"]: row["sha256"] for row in csv.DictReader(f)}
    status = {}
    for name in ["sample_manifest.csv", "slide_manifest.csv"]:
        path = self.data_dir / name
        status[name] = {"present": path.exists(), "verified": None, "sha256": sha256(path) if path.exists() else None,
                        "note": "committed manifest"}
    for table, name in RAW_FILES.items():
        path = self.data_dir / "raw" / name
        entry = {"present": path.exists(), "verified": None, "sha256": None, "note": ""}
        if path.exists():
            entry["sha256"] = sha256(path)
            if name in expected:
                entry["verified"] = entry["sha256"] == expected[name]
                entry["note"] = "matches the frozen checksum" if entry["verified"] else \
                    "DOES NOT match the frozen checksum: tell the organizers and don't use it for judged results"
        else:
            entry["note"] = "not downloaded yet: run python data/tcga-brca/fetch.py"
        status[name] = entry

def available(self, table):
    if table in ("manifest", "slides", "normals"):
        return True
    entry = self.file_status.get(RAW_FILES.get(table, ""), {})
    return bool(entry.get("present")) and entry.get("verified") is not False

